/**
 * Cloudflare Worker entry (wrangler.jsonc → "main").
 *
 * Wraps the worker generated by `opennextjs-cloudflare build` and adds one
 * thing: optimised photographs (/_next/image) are stored in Cloudflare's edge
 * cache, so each size/format of a photograph is transformed by the Images
 * binding once per data centre instead of on every request.
 *
 * Only content-addressed sources (/media-cache/<hash>/…, written at build time
 * by scripts/media/generate-image-manifest.mjs) whose response OpenNext marked
 * immutable are cached. A replaced photograph has a new hash and therefore a
 * new URL and cache key, so nothing stale is ever served. Everything else is
 * passed straight to the OpenNext worker unchanged.
 */

// Generated by `opennextjs-cloudflare build`, so it may or may not exist when type-checking;
// (an expect-error directive would then fail), hence the ignore below.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import openNextWorker from "./.open-next/worker.js";

type Ctx = { waitUntil(promise: Promise<unknown>): void; passThroughOnException?(): void };
type Handler = { fetch(request: Request, env: unknown, ctx: Ctx): Promise<Response> };

const worker = openNextWorker as Handler;
/** Must match `images.formats` in next.config.ts, in the same order (OpenNext picks the first the browser accepts). */
const FORMATS = ["image/avif", "image/webp"];

const handler: Handler = {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const source = url.pathname === "/_next/image" ? (url.searchParams.get("url") ?? "") : "";
    if (request.method !== "GET" || !source.startsWith("/media-cache/")) return worker.fetch(request, env, ctx);

    // The response varies by the format negotiated from Accept; the edge cache
    // ignores Vary, so the format is part of the key.
    const accept = request.headers.get("Accept") ?? "";
    const key = new URL(url);
    key.searchParams.set("__format", FORMATS.find((f) => accept.includes(f)) ?? "original");

    const cache = (globalThis as unknown as { caches: { default: Cache } }).caches.default;
    // The cache only ever speeds things up: if it fails, serve the image normally.
    const cached = await cache.match(key.toString()).catch(() => undefined);
    if (cached) {
      const hit = new Response(cached.body, cached);
      hit.headers.set("Vary", "Accept");
      hit.headers.set("X-Image-Cache", "HIT");
      return hit;
    }

    const response = await worker.fetch(request, env, ctx);
    if (response.status !== 200 || !(response.headers.get("Cache-Control") ?? "").includes("immutable")) return response;

    const stored = new Response(response.clone().body, response);
    stored.headers.delete("Vary");
    ctx.waitUntil(cache.put(key.toString(), stored).catch(() => undefined));
    const miss = new Response(response.body, response);
    miss.headers.set("X-Image-Cache", "MISS");
    return miss;
  },
};

export default handler;
